function PlayerCarouselSlide({
  index,
  children,
  className,
  style,
  ...props
}: PlayerCarouselSlideProps) {
  const {
    slideWidthRem,
    slideTransitionDurationMs,
    slideTransitionTimingFunction,
    selectedIndex,
    setSelectedIndex,
    registerSlideRef,
  } = usePlayerCarouselContext("Slide");
  const enterStyle = useCarouselEnterMotion("Slide", index);
  const active = index === selectedIndex;
  const widthTransition = `width ${slideTransitionDurationMs}ms ${slideTransitionTimingFunction}`;

  return (
    <div
      ref={(node) => registerSlideRef(index, node)}
      data-vp-carousel-part="slide"
      data-vp-carousel-slide-index={index}
      role="button"
      tabIndex={0}
      data-vp-carousel-slide-active={active ? "" : undefined}
      className={cn("flex shrink-0 cursor-pointer flex-col", className)}
      style={{
        width: `${
          slideWidthRem * (active ? PLAYER_CAROUSEL_ACTIVE_MEDIA_SCALE : 1)
        }rem`,
        ...enterStyle,
        transition: enterStyle?.transition
          ? `${widthTransition}, ${enterStyle.transition}`
          : widthTransition,
        ...style,
      }}
      onClick={() => setSelectedIndex(index)}
      onKeyDown={(event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          setSelectedIndex(index);
        }
      }}
      {...props}
    >
      {children}
    </div>
  );
}

